/* TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX. */
#include "unity.h"
#include "recording_session.h"
#include "storage_port_fake.h"
#include <string.h>

static uint8_t chunk[64];

void setUp(void)
{
    StoragePortFake_Reset();
    memset(chunk, 0xAA, sizeof(chunk));
}

void tearDown(void) {}

void test_start_initialises_idle_fields_to_recording(void)
{
    recording_session_t s;
    recording_start(&s);

    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state);
    TEST_ASSERT_EQUAL_UINT32(0U, s.bytes_written);
    TEST_ASSERT_EQUAL_UINT8(0U, s.consecutive_slow_writes);
}

void test_successful_write_accumulates_bytes_written(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);

    storage_result_t result = recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL(STORAGE_OK, result);
    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state);
    TEST_ASSERT_EQUAL_UINT32(sizeof(chunk), s.bytes_written);
    TEST_ASSERT_EQUAL_INT(1, StoragePortFake_GetWriteCallCount());
}

void test_multiple_writes_accumulate_correctly(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL_UINT32(sizeof(chunk) * 3U, s.bytes_written);
    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state);
}

void test_write_fail_enters_fault_and_preserves_bytes_written(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);
    recording_write_chunk(&s, chunk, sizeof(chunk)); /* succeeds first */

    StoragePortFake_QueueWriteResult(STORAGE_WRITE_FAIL);
    storage_result_t result = recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL(STORAGE_WRITE_FAIL, result);
    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);
    TEST_ASSERT_EQUAL(STORAGE_WRITE_FAIL, s.last_fault);
    /* The chunk before the failure must remain counted - "preserve the
     * last valid stored data" (1.9). */
    TEST_ASSERT_EQUAL_UINT32(sizeof(chunk), s.bytes_written);
}

void test_card_full_enters_fault(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_FULL);

    storage_result_t result = recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL(STORAGE_FULL, result);
    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);
    TEST_ASSERT_EQUAL(STORAGE_FULL, s.last_fault);
}

void test_writes_after_fault_are_rejected(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_WRITE_FAIL);
    recording_write_chunk(&s, chunk, sizeof(chunk)); /* -> FAULT */

    int calls_before = StoragePortFake_GetWriteCallCount();
    storage_result_t result = recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, result);
    /* Must not have reached the storage port at all while faulted. */
    TEST_ASSERT_EQUAL_INT(calls_before, StoragePortFake_GetWriteCallCount());
}

void test_slow_writes_below_threshold_continue_recording(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    storage_result_t result = recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL(STORAGE_SLOW, result);
    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state);
    TEST_ASSERT_EQUAL_UINT8(2U, s.consecutive_slow_writes);
}

void test_slow_writes_reaching_threshold_stops_recording_safely(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_write_chunk(&s, chunk, sizeof(chunk));
    storage_result_t result = recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL(STORAGE_SLOW, result);
    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);
    TEST_ASSERT_EQUAL(STORAGE_SLOW, s.last_fault);
}

void test_slow_write_counter_resets_after_a_good_write(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);
    StoragePortFake_QueueWriteResult(STORAGE_OK);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);

    recording_write_chunk(&s, chunk, sizeof(chunk)); /* slow: 1 */
    recording_write_chunk(&s, chunk, sizeof(chunk)); /* slow: 2 */
    recording_write_chunk(&s, chunk, sizeof(chunk)); /* OK: reset to 0 */
    recording_write_chunk(&s, chunk, sizeof(chunk)); /* slow: 1 */
    storage_result_t result = recording_write_chunk(&s, chunk, sizeof(chunk)); /* slow: 2 */

    TEST_ASSERT_EQUAL(STORAGE_SLOW, result);
    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state); /* never hit 3 in a row */
    TEST_ASSERT_EQUAL_UINT8(2U, s.consecutive_slow_writes);
}

void test_stop_while_recording_returns_to_idle(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);
    recording_write_chunk(&s, chunk, sizeof(chunk));

    recording_stop(&s);

    TEST_ASSERT_EQUAL(REC_STATE_IDLE, s.state);
}

void test_stop_while_faulted_leaves_fault_state_visible(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_WRITE_FAIL);
    recording_write_chunk(&s, chunk, sizeof(chunk));

    recording_stop(&s);

    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);
}

void test_zero_length_write_is_rejected(void)
{
    recording_session_t s;
    recording_start(&s);

    storage_result_t result = recording_write_chunk(&s, chunk, 0U);

    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, result);
    TEST_ASSERT_EQUAL_INT(0, StoragePortFake_GetWriteCallCount());
}


/* ---------- argument validation ---------- */

void test_null_session_is_rejected(void)
{
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        recording_write_chunk(NULL, chunk, sizeof(chunk)));
}

void test_null_data_pointer_is_rejected(void)
{
    recording_session_t s;
    recording_start(&s);
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        recording_write_chunk(&s, NULL, sizeof(chunk)));
    TEST_ASSERT_EQUAL_INT(0, StoragePortFake_GetWriteCallCount());
}

void test_null_session_start_and_stop_do_not_crash(void)
{
    recording_start(NULL);
    recording_stop(NULL);
    TEST_PASS();
}

/* ---------- state transitions ---------- */

void test_write_before_start_is_rejected(void)
{
    recording_session_t s;
    memset(&s, 0, sizeof(s));
    s.state = REC_STATE_IDLE;

    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        recording_write_chunk(&s, chunk, sizeof(chunk)));
    TEST_ASSERT_EQUAL_INT(0, StoragePortFake_GetWriteCallCount());
}

void test_write_after_stop_is_rejected(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);
    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_stop(&s);

    int calls_before = StoragePortFake_GetWriteCallCount();
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG,
        recording_write_chunk(&s, chunk, sizeof(chunk)));
    TEST_ASSERT_EQUAL_INT(calls_before, StoragePortFake_GetWriteCallCount());
}

void test_restarting_after_a_fault_clears_the_fault(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_WRITE_FAIL);
    recording_write_chunk(&s, chunk, sizeof(chunk));
    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);

    recording_start(&s);
    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state);
    TEST_ASSERT_EQUAL(STORAGE_OK, s.last_fault);
    TEST_ASSERT_EQUAL_UINT32(0U, s.bytes_written);
    TEST_ASSERT_EQUAL_UINT8(0U, s.consecutive_slow_writes);
}

void test_restarting_resets_byte_counter_between_recordings(void)
{
    recording_session_t s;
    StoragePortFake_QueueWriteResult(STORAGE_OK);

    recording_start(&s);
    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_stop(&s);
    TEST_ASSERT_EQUAL_UINT32(sizeof(chunk), s.bytes_written);

    recording_start(&s);
    TEST_ASSERT_EQUAL_UINT32(0U, s.bytes_written);
}

void test_stop_from_idle_leaves_session_idle(void)
{
    recording_session_t s;
    recording_start(&s);
    recording_stop(&s);
    recording_stop(&s); /* stopping twice must be harmless */
    TEST_ASSERT_EQUAL(REC_STATE_IDLE, s.state);
}

/* ---------- slow-write threshold boundaries ---------- */

void test_slow_write_counter_increments_by_one_per_slow_write(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    TEST_ASSERT_EQUAL_UINT8(1U, s.consecutive_slow_writes);
}

void test_slow_write_one_below_threshold_still_records(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);

    for (uint8_t i = 0U; i < (RECORDING_MAX_CONSECUTIVE_SLOW_WRITES - 1U); i++)
    {
        recording_write_chunk(&s, chunk, sizeof(chunk));
    }
    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state);
}

void test_slow_write_data_is_still_counted_as_written(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    /* A slow write still lands on the card, so the bytes must be counted. */
    TEST_ASSERT_EQUAL_UINT32(sizeof(chunk), s.bytes_written);
}

void test_write_fail_after_slow_writes_reports_the_write_failure(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_SLOW);
    StoragePortFake_QueueWriteResult(STORAGE_WRITE_FAIL);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_write_chunk(&s, chunk, sizeof(chunk));

    /* The hard failure, not the earlier slow write, is the reported cause. */
    TEST_ASSERT_EQUAL(STORAGE_WRITE_FAIL, s.last_fault);
}

/* ---------- unexpected results ---------- */

void test_unexpected_storage_result_is_treated_as_a_fault(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_CORRUPT);

    recording_write_chunk(&s, chunk, sizeof(chunk));

    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, s.last_fault);
}

void test_not_found_result_is_treated_as_a_fault(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_NOT_FOUND);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);
}

/* ---------- multi-step realistic sequences ---------- */

void test_long_recording_of_many_chunks_accumulates_correctly(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);

    const uint32_t num_chunks = 100U;
    for (uint32_t i = 0U; i < num_chunks; i++)
    {
        recording_write_chunk(&s, chunk, sizeof(chunk));
    }

    TEST_ASSERT_EQUAL(REC_STATE_RECORDING, s.state);
    TEST_ASSERT_EQUAL_UINT32(num_chunks * sizeof(chunk), s.bytes_written);
    TEST_ASSERT_EQUAL_INT((int)num_chunks, StoragePortFake_GetWriteCallCount());
}

void test_full_record_stop_record_cycle(void)
{
    recording_session_t s;
    StoragePortFake_QueueWriteResult(STORAGE_OK);

    /* First recording */
    recording_start(&s);
    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_stop(&s);
    TEST_ASSERT_EQUAL(REC_STATE_IDLE, s.state);

    /* Second recording is independent of the first */
    recording_start(&s);
    recording_write_chunk(&s, chunk, sizeof(chunk));
    TEST_ASSERT_EQUAL_UINT32(sizeof(chunk), s.bytes_written);
    recording_stop(&s);
    TEST_ASSERT_EQUAL(REC_STATE_IDLE, s.state);
}

void test_card_removed_midway_stops_and_preserves_earlier_data(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);
    StoragePortFake_QueueWriteResult(STORAGE_OK);
    StoragePortFake_QueueWriteResult(STORAGE_WRITE_FAIL);

    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_write_chunk(&s, chunk, sizeof(chunk));
    recording_write_chunk(&s, chunk, sizeof(chunk)); /* card yanked */

    TEST_ASSERT_EQUAL(REC_STATE_FAULT, s.state);
    /* Two good chunks must remain accounted for (1.9). */
    TEST_ASSERT_EQUAL_UINT32(2U * sizeof(chunk), s.bytes_written);
}

void test_bytes_written_matches_bytes_seen_by_the_storage_layer(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);

    recording_write_chunk(&s, chunk, 16U);
    recording_write_chunk(&s, chunk, 32U);
    recording_write_chunk(&s, chunk, 8U);

    TEST_ASSERT_EQUAL_UINT32(56U, s.bytes_written);
    TEST_ASSERT_EQUAL_UINT32(56U, (uint32_t)StoragePortFake_GetTotalBytesWritten());
}

void test_varying_chunk_sizes_are_all_accepted(void)
{
    recording_session_t s;
    recording_start(&s);
    StoragePortFake_QueueWriteResult(STORAGE_OK);

    TEST_ASSERT_EQUAL(STORAGE_OK, recording_write_chunk(&s, chunk, 1U));
    TEST_ASSERT_EQUAL(STORAGE_OK, recording_write_chunk(&s, chunk, sizeof(chunk)));
    TEST_ASSERT_EQUAL_UINT32(1U + sizeof(chunk), s.bytes_written);
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_start_initialises_idle_fields_to_recording);
    RUN_TEST(test_successful_write_accumulates_bytes_written);
    RUN_TEST(test_multiple_writes_accumulate_correctly);
    RUN_TEST(test_write_fail_enters_fault_and_preserves_bytes_written);
    RUN_TEST(test_card_full_enters_fault);
    RUN_TEST(test_writes_after_fault_are_rejected);
    RUN_TEST(test_slow_writes_below_threshold_continue_recording);
    RUN_TEST(test_slow_writes_reaching_threshold_stops_recording_safely);
    RUN_TEST(test_slow_write_counter_resets_after_a_good_write);
    RUN_TEST(test_stop_while_recording_returns_to_idle);
    RUN_TEST(test_stop_while_faulted_leaves_fault_state_visible);
    RUN_TEST(test_zero_length_write_is_rejected);
    RUN_TEST(test_null_session_is_rejected);
    RUN_TEST(test_null_data_pointer_is_rejected);
    RUN_TEST(test_null_session_start_and_stop_do_not_crash);
    RUN_TEST(test_write_before_start_is_rejected);
    RUN_TEST(test_write_after_stop_is_rejected);
    RUN_TEST(test_restarting_after_a_fault_clears_the_fault);
    RUN_TEST(test_restarting_resets_byte_counter_between_recordings);
    RUN_TEST(test_stop_from_idle_leaves_session_idle);
    RUN_TEST(test_slow_write_counter_increments_by_one_per_slow_write);
    RUN_TEST(test_slow_write_one_below_threshold_still_records);
    RUN_TEST(test_slow_write_data_is_still_counted_as_written);
    RUN_TEST(test_write_fail_after_slow_writes_reports_the_write_failure);
    RUN_TEST(test_unexpected_storage_result_is_treated_as_a_fault);
    RUN_TEST(test_not_found_result_is_treated_as_a_fault);
    RUN_TEST(test_long_recording_of_many_chunks_accumulates_correctly);
    RUN_TEST(test_full_record_stop_record_cycle);
    RUN_TEST(test_card_removed_midway_stops_and_preserves_earlier_data);
    RUN_TEST(test_bytes_written_matches_bytes_seen_by_the_storage_layer);
    RUN_TEST(test_varying_chunk_sizes_are_all_accepted);
    return UNITY_END();
}
